const { seg, lerp, eo, eio } = kit;
/* The concept home's own intro (index-new-concept.html, "Logo intro" + "Hero
   entrance"), at its own times and curves, in page seconds P (film t = P - OFF;
   OFF 0: the film opens on the blank cover, as the page does).
     0.2   each letter's outline draws (80 ms stagger, 0.95 s), then fills as it closes
     1.6   a soft violet-to-cyan glow blooms behind the mark
     1.85  the mark glides into its slot (1.4 s, ease-in-out); the cover dissolves
           onto the hero gradient
     3.0   the headline's words blur and rise in (65 ms stagger), then the subline
     4.85  tile 1 rises; the headline and gradient lift away; the mark stays */
const OFF = 0;
const P = { start: 0.2, stag: 0.08, draw: 0.95, filled: 1.85, glide: 1.4, cover: [2.05, 2.95], words: 3.0, sub: 3.4, rise: [4.85, 5.55] };
const bez = (x1, y1, x2, y2) => (x) => {
  if (x <= 0) return 0;
  if (x >= 1) return 1;
  let lo = 0, hi = 1, u = x;
  for (let i = 0; i < 22; i++) { u = (lo + hi) / 2; if (3 * (1 - u) * (1 - u) * u * x1 + 3 * (1 - u) * u * u * x2 + u * u * u < x) lo = u; else hi = u; }
  return 3 * (1 - u) * (1 - u) * u * y1 + 3 * (1 - u) * u * u * y2 + u * u * u;
};
const DRAW = bez(0.33, 0, 0.2, 1), SOFT = bez(0.22, 1, 0.36, 1), GLIDE = bez(0.65, 0, 0.35, 1), RISE = bez(0.25, 0.1, 0.25, 1), OUT = bez(0, 0, 0.58, 1);
/* the hero gradient (index-new-concept.html, "Hero gradient (concept)") */
const FIELDS = [
  ['161 129 255', 0.62, 0.34, 0.11, 560, 430, 0.0],
  ['127 176 255', 0.62, 0.34, 0.11, 760, 660, 1.7],
  ['255 138 180', 0.58, 0.32, 0.10, 1360, 410, 3.1],
  ['255 178 140', 0.55, 0.30, 0.10, 1180, 680, 4.4],
];
const FW = 1000, FH = 770, PI2 = Math.PI * 2;
const LOGO = { x: 550, y: 458, w: 820 };
kit.scene('intro', {
  init(kit) {
    kit.css('.intro-aurora { position:absolute; inset:0; overflow:hidden; opacity:.5 } ' +
      '.intro-aurora span { position:absolute; left:0; top:0; width:' + FW + 'px; height:' + FH + 'px; border-radius:50% } ' +
      '.intro-scrim { position:absolute; inset:0; background:linear-gradient(180deg, rgba(251,251,250,.16) 0%, rgba(251,251,250,.28) 45%, rgba(251,251,250,.5) 82%, rgba(255,255,255,1) 100%) } ' +
      '.intro-cover { position:absolute; inset:0; background:#FBFBFA } ' +
      '.intro-glow { position:absolute; left:636px; top:216px; width:648px; height:648px; border-radius:50%; background:radial-gradient(closest-side, rgb(139 87 199 / .20), rgb(33 164 215 / .08) 55%, transparent) } ' +
      '.intro-logo { position:absolute; transform-origin:50% 50% } .intro-logo path { stroke-linejoin:round; stroke-dasharray:1 1 } ' +
      '.intro-title { font-size:96px; line-height:1.06; letter-spacing:-0.03em } .intro-title > span, .intro-sub > span { display:block } ' +
      '.intro-sub { font-size:32px; line-height:1.5; color:color-mix(in srgb, var(--second) 80%, var(--ground)) }');
    const fields = FIELDS.map(([c, a, b, d]) =>
      '<span style="background:radial-gradient(closest-side, rgb(' + c + ' / ' + a + '), rgb(' + c + ' / ' + b + ') 40%, rgb(' + c + ' / ' + d + ') 70%, transparent)"></span>').join('');
    kit.stage.append(kit.h('<div class="ground"><div class="intro-aurora">' + fields + '</div><div class="intro-scrim"></div></div>'));
    this.aurora = kit.stage.querySelector('.intro-aurora').style;
    this.fields = [...kit.stage.querySelectorAll('.intro-aurora span')].map((el) => el.style);

    /* a two-line headline (the words set by hand on the page), then a two-line description */
    const head = kit.h('<div class="words intro-head" style="left:260px;width:1400px;top:372px;align-items:center;text-align:center;gap:30px">' +
      '<h2 class="line intro-title"><span>One pattern library</span><span>for every user</span></h2>' +
      '<p class="sub intro-sub"><span>Describe the screen. Nucleux picks the patterns.</span><span>Your agent builds the live preview.</span></p></div>');
    kit.stage.append(head);
    this.head = head.style;
    this.sub = head.querySelector('.sub').style;
    /* word by word, across both lines, as the hero does */
    this.words = [];
    head.querySelectorAll('.intro-title > span').forEach((ln) => {
      const words = ln.textContent.split(' ');
      ln.textContent = '';
      words.forEach((w, i) => {
        const sp = kit.el('span', { text: w, style: 'display:inline-block' });
        ln.append(sp);
        if (i < words.length - 1) ln.append(' ');
        this.words.push(sp.style);
      });
    });

    this.t1 = window.HWF.tile(kit, 0, 0);

    kit.stage.append(kit.h('<div class="intro-cover"></div>'));
    kit.stage.append(kit.h('<div class="intro-glow"></div>'));
    const logo = kit.h('<div class="intro-logo" style="left:' + LOGO.x + 'px;top:' + LOGO.y + 'px;width:' + LOGO.w + 'px">' + window.HWF.markSvg('intro') + '</div>');
    kit.stage.append(logo);
    this.cover = kit.stage.querySelector('.intro-cover').style;
    this.glow = kit.stage.querySelector('.intro-glow').style;
    this.logo = logo.style;
    this.paths = [...logo.querySelectorAll('path')].map((p) => {
      p.style.stroke = p.getAttribute('fill');
      return p.style;
    });
    /* the glide: from the centre of the stage to the slot the later scenes keep it in */
    const S = window.HWF.SLOT, k = S.w / LOGO.w;
    this.fly = { dx: S.x + S.w / 2 - (LOGO.x + LOGO.w / 2), dy: S.y + (S.w * 24 / 120) / 2 - (LOGO.y + (LOGO.w * 24 / 120) / 2), k };
  },
  render(t) {
    const p = t + OFF;
    /* 1. outline, then fill, letter by letter */
    this.paths.forEach((s, i) => {
      const d = P.start + i * P.stag;
      const f = SOFT(seg(p, d + P.draw - 0.26, d + P.draw + 0.22));
      const dr = DRAW(seg(p, d, d + P.draw));
      s.strokeDashoffset = (1 - dr).toFixed(4);
      s.fillOpacity = f.toFixed(3);
      /* no stroke until the outline starts: a zero-length dash still paints a dot */
      s.strokeWidth = dr > 0 ? (0.32 * (1 - f)).toFixed(3) : '0';
    });
    /* 2. the glow blooms, then lets go as the mark leaves */
    const g = SOFT(seg(p, P.filled - 0.25, P.filled + 0.65));
    const gIn = SOFT(seg(P.filled, P.filled - 0.25, P.filled + 0.65));
    this.glow.opacity = (p < P.filled ? g : gIn * (1 - seg(p, P.filled, P.filled + 0.42))).toFixed(3);
    this.glow.transform = 'scale(' + lerp(0.4, 1, g).toFixed(4) + ')';
    /* 3. one calm glide into the slot: size and place share one curve, no overshoot */
    const m = GLIDE(seg(p, P.filled, P.filled + P.glide));
    this.logo.transform = 'translate(' + (this.fly.dx * m).toFixed(1) + 'px,' + (this.fly.dy * m).toFixed(1) + 'px) scale(' + lerp(1, this.fly.k, m).toFixed(4) + ')';
    this.cover.opacity = (1 - OUT(seg(p, P.cover[0], P.cover[1]))).toFixed(3);
    /* 4. the hero gradient underneath, drifting and breathing */
    this.fields.forEach((s, i) => {
      const [, , , , x, y, ph] = FIELDS[i];
      const dx = 70 * Math.sin(PI2 * (p + ph) / 5.5), dy = 46 * Math.cos(PI2 * (p + ph) / 6.5);
      s.transform = 'translate(' + (x - FW / 2 + dx).toFixed(1) + 'px,' + (y - FH / 2 + dy).toFixed(1) + 'px) scale(' + (1 + 0.06 * Math.sin(PI2 * (p + ph) / 7)).toFixed(4) + ')';
      s.opacity = (0.82 + 0.18 * Math.sin(PI2 * (p + ph) / 4.5)).toFixed(3);
    });
    /* 5. the hero entrance: words blur and rise in one by one, then the subline */
    this.words.forEach((s, i) => {
      const w = RISE(seg(p, P.words + i * 0.065, P.words + i * 0.065 + 0.4));
      s.opacity = w.toFixed(3);
      s.filter = w < 1 ? 'blur(' + (12 * (1 - w)).toFixed(2) + 'px)' : 'none';
      s.transform = 'translateY(' + (24 * (1 - w)).toFixed(2) + 'px)';
    });
    const u = RISE(seg(p, P.sub, P.sub + 0.42));
    this.sub.opacity = u.toFixed(3);
    this.sub.filter = u < 1 ? 'blur(' + (10 * (1 - u)).toFixed(2) + 'px)' : 'none';
    this.sub.transform = 'translateY(' + (20 * (1 - u)).toFixed(2) + 'px)';
    /* 6. tile 1 rises; the headline and the gradient lift away */
    const r = eio(seg(p, P.rise[0], P.rise[1]));
    this.head.transform = 'translateY(' + (lerp(0, -320, r) - Math.max(0, p - P.words) * 3).toFixed(1) + 'px)';
    this.head.opacity = (1 - eo(seg(p, P.rise[0] + 0.05, P.rise[0] + 0.55))).toFixed(3);
    this.aurora.opacity = (0.5 * (1 - eo(seg(p, P.rise[0] + 0.05, P.rise[1] - 0.05)))).toFixed(3);
    this.aurora.transform = 'translateY(' + lerp(0, -140, r).toFixed(1) + 'px)';
    this.t1.s.transform = 'translateY(' + lerp(1040, 0, r).toFixed(1) + 'px)';
  },
});
